#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<vector<int>> positions(3);
    vector<int> counts(3, 0);
    for (int i = 0; i < n; i++) {
        char ch = s[i];
        if (ch == 'V') {
            positions[0].push_back(i);
            counts[0]++;
        } else if (ch == 'K') {
            positions[1].push_back(i);
            counts[1]++;
        } else {
            positions[2].push_back(i);
            counts[2]++;
        }
    }

    int maxA = counts[0], maxB = counts[1], maxC = counts[2];

    vector<vector<vector<int>>> p(3, vector<vector<int>>(3, vector<int>(n, 0)));
    for (int x = 0; x < 3; x++) {
        for (int y = 0; y < 3; y++) {
            if (x != y) {
                for (int i = 0; i < counts[x]; i++) {
                    for (int j = 0; j < counts[y]; j++) {
                        if (positions[y][j] < positions[x][i]) {
                            p[x][y][i]++;
                        }
                    }
                }
            }
        }
    }

    const int INF = 1000000000;
    vector<vector<vector<vector<int>>>> dp(maxA + 1, vector<vector<vector<int>>>(maxB + 1, vector<vector<int>>(maxC + 1, vector<int>(2, INF))));
    dp[0][0][0][1] = 0;

    for (int i = 0; i <= maxA; i++) {
        for (int j = 0; j <= maxB; j++) {
            for (int k = 0; k <= maxC; k++) {
                for (int q = 0; q < 2; q++) {
                    int current = dp[i][j][k][q];
                    if (current == INF) continue;
                    if (i < maxA) {
                        int cost = current + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0);
                        if (cost < dp[i + 1][j][k][0]) {
                            dp[i + 1][j][k][0] = cost;
                        }
                    }
                    if (j < maxB && q == 1) {
                        int cost = current + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0);
                        if (cost < dp[i][j + 1][k][1]) {
                            dp[i][j + 1][k][1] = cost;
                        }
                    }
                    if (k < maxC) {
                        int cost = current + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0);
                        if (cost < dp[i][j][k + 1][1]) {
                            dp[i][j][k + 1][1] = cost;
                        }
                    }
                }
            }
        }
    }

    int answer = min(dp[maxA][maxB][maxC][0], dp[maxA][maxB][maxC][1]);
    cout << answer << "\n";

    return 0;
}
